func:
// ======================================================
// ECOBOT SOLCON - CONFIGURAÇÕES
// Editar os valores abaixo antes de usar o fluxo.
// ======================================================

const config = {
    // Telegram BotFather
    telegramToken: "8862631001:AAG7iCG_U7YHhNVjnLtPaZgiX67Ejm1hSS8",

    // Watson Assistant v2
    assistantApiKey: "XCIU4Rb89TQQSrf0CKQsUUA6_w_3VJrine4Ue7ZrjaQ9",
    assistantUrl: "https://api.us-south.assistant.watson.cloud.ibm.com/instances/d7967282-8d3a-4b1d-b60a-42928b0d6eb6",
    assistantId: "c09c9c75-03de-4549-9358-1aa84de5b921",

    // IBM Speech to Text
    sttApiKey: "N20ClYCdUkocf9mTMOIg5r0yi7r2mI5m-T8AKw9q6L0Z",
    sttUrl: "https://api.au-syd.speech-to-text.watson.cloud.ibm.com/instances/216c5954-e3a0-48ad-a56c-cafced2448b9",
    sttModel: "pt-BR_BroadbandModel",

    // IBM Text to Speech
    ttsApiKey: "1JKQpvBSn4DO4nNGUTSLogz4DKx-XUyVBcEDovv1Hzz8",
    ttsUrl: "https://api.au-syd.text-to-speech.watson.cloud.ibm.com/instances/15710039-473d-486e-8049-75bb8a026f12",
    ttsVoice: "pt-BR_IsabelaV3Voice",

    // Sessão do Assistant: renova após 25 minutos
    sessionTtlMs: 25 * 60 * 1000
};

global.set("ECOBOT_SOLCON_CONFIG", config);
global.set("ECOBOT_SOLCON_WA_SESSIONS", {});

msg.payload = "Configurações do EcoBot SolCon salvas no contexto global. Agora fazer Deploy e testar no Telegram.";
return msg;

const p = msg.payload || {};
const original = msg.originalMessage || {};
const chatId = p.chatId || (p.chat && p.chat.id) || (original.chat && original.chat.id) || (original.message && original.message.chat && original.message.chat.id);

msg.ecobot = {
    chatId: chatId,
    originalPayload: p,
    replyAsAudio: false
};

// Texto normal
if (typeof p.content === "string" && p.content.trim() !== "") {
    msg.userText = p.content.trim();
    msg.ecobot.replyAsAudio = false;
    return [msg, null, null];
}

if (typeof p.text === "string" && p.text.trim() !== "") {
    msg.userText = p.text.trim();
    msg.ecobot.replyAsAudio = false;
    return [msg, null, null];
}

// Áudio/voz do Telegram
let fileId = null;

if (p.content && typeof p.content === "object") {
    fileId = p.content.file_id || (p.content.voice && p.content.voice.file_id) || (p.content.audio && p.content.audio.file_id);
}

fileId = fileId
    || (p.voice && p.voice.file_id)
    || (p.audio && p.audio.file_id)
    || (original.voice && original.voice.file_id)
    || (original.audio && original.audio.file_id)
    || (original.message && original.message.voice && original.message.voice.file_id)
    || (original.message && original.message.audio && original.message.audio.file_id);

if (fileId) {
    msg.ecobot.fileId = fileId;
    msg.ecobot.replyAsAudio = true;
    return [null, msg, null];
}

return [null, null, msg];

msg.payload = {
    chatId: msg.ecobot && msg.ecobot.chatId,
    type: "message",
    content: "No momento eu consigo entender mensagens de texto e áudio. Envie sua dúvida sobre ações sustentáveis, evidências, pontos, ranking ou impacto ambiental."
};
return msg;

const cfg = global.get("ECOBOT_SOLCON_CONFIG") || {};
if (!cfg.telegramToken || cfg.telegramToken.includes("COLE_AQUI")) {
    node.error("Configure telegramToken no nó CONFIGURAR CREDENCIAIS.", msg);
    return null;
}
msg.method = "GET";
msg.url = `https://api.telegram.org/bot${cfg.telegramToken}/getFile?file_id=${msg.ecobot.fileId}`;
return msg;

const cfg = global.get("ECOBOT_SOLCON_CONFIG") || {};
const filePath = msg.payload && msg.payload.result && msg.payload.result.file_path;
if (!filePath) {
    msg.payload = { chatId: msg.ecobot.chatId, type: "message", content: "Não consegui baixar o áudio do Telegram. Tente enviar novamente em formato de voz." };
    return [null, msg];
}
msg.method = "GET";
msg.url = `https://api.telegram.org/file/bot${cfg.telegramToken}/${filePath}`;
return [msg, null];

const cfg = global.get("ECOBOT_SOLCON_CONFIG") || {};
if (!cfg.sttApiKey || cfg.sttApiKey.includes("COLE_AQUI")) { node.error("Configure sttApiKey no nó CONFIGURAR CREDENCIAIS.", msg); return null; }
msg.audioBuffer = msg.payload;
msg.method = "POST";
msg.url = "https://iam.cloud.ibm.com/identity/token";
msg.headers = {"Content-Type": "application/x-www-form-urlencoded"};
msg.payload = "grant_type=urn:ibm:params:oauth:grant-type:apikey&apikey=" + encodeURIComponent(cfg.sttApiKey);
return msg;

const cfg = global.get("ECOBOT_SOLCON_CONFIG") || {};
const token = msg.payload && msg.payload.access_token;
if (!token) { msg.payload = { chatId: msg.ecobot.chatId, type: "message", content: "Não consegui autenticar o Speech to Text. Confira a API Key do serviço." }; return [null, msg]; }
msg.method = "POST";
msg.url = `${cfg.sttUrl}/v1/recognize?model=${encodeURIComponent(cfg.sttModel || "pt-BR_BroadbandModel")}`;
msg.headers = { "Authorization": "Bearer " + token, "Content-Type": "audio/ogg;codecs=opus", "Accept": "application/json" };
msg.payload = msg.audioBuffer;
return [msg, null];

const results = msg.payload && msg.payload.results ? msg.payload.results : [];
const text = results.map(r => r.alternatives && r.alternatives[0] && r.alternatives[0].transcript).filter(Boolean).join(" ").trim();
if (!text) { msg.payload = { chatId: msg.ecobot.chatId, type: "message", content: "Não consegui entender o áudio. Tente falar mais perto do microfone ou envie por texto." }; return [null, msg]; }
msg.userText = text;
msg.ecobot.replyAsAudio = true;
return [msg, null];

const cfg = global.get("ECOBOT_SOLCON_CONFIG") || {};
if (!cfg.assistantApiKey || cfg.assistantApiKey.includes("COLE_AQUI")) { node.error("Configure assistantApiKey no nó CONFIGURAR CREDENCIAIS.", msg); return null; }
msg.method = "POST";
msg.url = "https://iam.cloud.ibm.com/identity/token";
msg.headers = {"Content-Type": "application/x-www-form-urlencoded"};
msg.payload = "grant_type=urn:ibm:params:oauth:grant-type:apikey&apikey=" + encodeURIComponent(cfg.assistantApiKey);
return msg;

const cfg = global.get("ECOBOT_SOLCON_CONFIG") || {};
const token = msg.payload && msg.payload.access_token;
if (!token) { msg.payload = { chatId: msg.ecobot.chatId, type: "message", content: "Não consegui autenticar o Watson Assistant. Confira a API Key." }; return [null, null, msg]; }
msg.waToken = token;
const chatId = String(msg.ecobot.chatId || "default");
const sessions = global.get("ECOBOT_SOLCON_WA_SESSIONS") || {};
const current = sessions[chatId];
const ttl = cfg.sessionTtlMs || (25 * 60 * 1000);
if (current && current.sessionId && (Date.now() - current.createdAt) < ttl) { msg.sessionId = current.sessionId; return [null, msg, null]; }
msg.method = "POST";
msg.url = `${cfg.assistantUrl}/v2/assistants/${cfg.assistantId}/sessions?version=2021-06-14`;
msg.headers = { "Authorization": "Bearer " + msg.waToken, "Content-Type": "application/json" };
msg.payload = {};
return [msg, null, null];

const sessionId = msg.payload && msg.payload.session_id;
if (!sessionId) { msg.payload = { chatId: msg.ecobot.chatId, type: "message", content: "Não consegui criar sessão no Watson Assistant. Confira Assistant ID e URL." }; return [null, msg]; }
msg.sessionId = sessionId;
const chatId = String(msg.ecobot.chatId || "default");
const sessions = global.get("ECOBOT_SOLCON_WA_SESSIONS") || {};
sessions[chatId] = { sessionId: sessionId, createdAt: Date.now() };
global.set("ECOBOT_SOLCON_WA_SESSIONS", sessions);
return [msg, null];

const cfg = global.get("ECOBOT_SOLCON_CONFIG") || {};
const text = (msg.userText || "").trim();
if (!text) { msg.payload = { chatId: msg.ecobot.chatId, type: "message", content: "Envie uma mensagem sobre EcoScore, ações sustentáveis, evidências, pontos, ranking ou impacto ambiental." }; return [null, msg]; }
msg.method = "POST";
msg.url = `${cfg.assistantUrl}/v2/assistants/${cfg.assistantId}/sessions/${msg.sessionId}/message?version=2021-06-14`;
msg.headers = { "Authorization": "Bearer " + msg.waToken, "Content-Type": "application/json" };
msg.payload = { input: { message_type: "text", text: text, options: { return_context: true } } };
return [msg, null];

const generic = msg.payload && msg.payload.output && msg.payload.output.generic ? msg.payload.output.generic : [];
let texts = generic.filter(item => item.response_type === "text" && item.text).map(item => item.text);
if (texts.length === 0) { texts = ["Não entendi totalmente. Posso ajudar com ações sustentáveis, evidências, validação, pontos, ranking, conquistas e impacto ambiental."]; }
msg.botText = texts.join("\n\n");
if (msg.botText.length > 900) { msg.botText = msg.botText.substring(0, 897) + "..."; }
return msg;

const cfg = global.get("ECOBOT_SOLCON_CONFIG") || {};
if (!cfg.ttsApiKey || cfg.ttsApiKey.includes("COLE_AQUI")) { node.error("Configure ttsApiKey no nó CONFIGURAR CREDENCIAIS.", msg); return null; }
msg.method = "POST";
msg.url = "https://iam.cloud.ibm.com/identity/token";
msg.headers = {"Content-Type": "application/x-www-form-urlencoded"};
msg.payload = "grant_type=urn:ibm:params:oauth:grant-type:apikey&apikey=" + encodeURIComponent(cfg.ttsApiKey);
return msg;

const cfg = global.get("ECOBOT_SOLCON_CONFIG") || {};
const token = msg.payload && msg.payload.access_token;
if (!token) { msg.payload = { chatId: msg.ecobot.chatId, type: "message", content: "Não consegui autenticar o Text to Speech. Confira a API Key." }; return [null, msg]; }
msg.method = "POST";
msg.url = `${cfg.ttsUrl}/v1/synthesize?voice=${encodeURIComponent(cfg.ttsVoice || "pt-BR_IsabelaV3Voice")}`;
msg.headers = { "Authorization": "Bearer " + token, "Content-Type": "application/json", "Accept": "audio/ogg;codecs=opus" };
msg.payload = { text: msg.botText };
return [msg, null];

// Envia resposta sintetizada como áudio/voz.
// Se seu Telegram Sender não aceitar type "voice", troque para type "audio".
msg.payload = { chatId: msg.ecobot.chatId, type: "voice", content: msg.payload };
return msg;

msg.ecobot = { chatId: "teste_local", replyAsAudio: false };
msg.userText = msg.payload;
return msg;
